public class WeatherService
{
    private readonly IDistributedCache _cache;
    private readonly JsonSerializerOptions _jsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase
    };

    public WeatherService(IDistributedCache cache)
    {
        _cache = cache;
    }

    public async Task<WeatherForecast[]> GetForecastAsync()
    {
    const string key = "weather-forecast";

    var cached = await _cache.GetStringAsync(key);
    if (cached is not null)
    {
        return JsonSerializer.Deserialize<WeatherForecast[]>(cached, _jsonOptions)!;
    }

    var forecast = GenerateForecast();
    var json = JsonSerializer.Serialize(forecast, _jsonOptions);

    await _cache.SetStringAsync(
        key,
        json,
        new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(15)
        });

    return forecast;
}
}
